package com.bananalab.lite;
import android.content.*;import org.json.*;
/** User reports and executable evidence have distinct provenance. No self-labeling as truth. */
final class LearningJournal{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-learning-journal",0);}
 static JSONArray rows(Context c)throws Exception{return new JSONArray(prefs(c).getString("rows","[]"));}
 static synchronized void add(Context c,String kind,String request,String result,int tests)throws Exception{JSONArray old=rows(c),next=new JSONArray();for(int i=Math.max(0,old.length()-47);i<old.length();i++)next.put(old.getJSONObject(i));next.put(new JSONObject().put("kind",kind).put("request",request.substring(0,Math.min(400,request.length()))).put("result",result.substring(0,Math.min(800,result.length()))).put("tests",tests).put("time",System.currentTimeMillis()));if(!prefs(c).edit().putString("rows",next.toString()).commit())throw new java.io.IOException("No pude guardar el registro.");}
 static void validate(JSONArray rows)throws Exception{if(rows.length()>48)throw new IllegalArgumentException("Demasiados registros.");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);RuntimeProgram.keys(row,"kind","request","result","tests","time");if(!row.getString("kind").matches("user_report|verified_program|verified_understanding|rejected_candidate")||row.getString("request").length()>400||row.getString("result").length()>800||row.getInt("tests")<0||row.getInt("tests")>10000)throw new IllegalArgumentException("Registro inválido.");row.getLong("time");}}
 static String report(Context c)throws Exception{JSONArray rows=rows(c);StringBuilder s=new StringBuilder("Memoria de fallos y pruebas · "+rows.length()+" registros\n");for(int i=Math.max(0,rows.length()-12);i<rows.length();i++){JSONObject row=rows.getJSONObject(i);s.append(row.getString("kind").equals("user_report")?"Aporte del usuario, sin verificar":row.getString("kind")).append(": ").append(row.getString("request")).append("\n").append(row.getString("result")).append(" · ").append(row.getInt("tests")).append(" pruebas\n");}return s.toString();}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(q.matches("mis fallos|memoria de fallos|que errores recordas|mostrame tus fallos"))return MobileCore.say(c,report(c),"aprendizaje_local");if(q.startsWith("registra este fallo ")||q.startsWith("ese cambio fallo ")){int at=input.indexOf(':');if(at<0)return MobileCore.say(c,"Contame el fallo después de dos puntos. Lo registraré como un reporte tuyo, no como una causa comprobada.","aprendizaje_local");String text=input.substring(at+1).trim();if(text.length()<3||text.length()>400)return MobileCore.say(c,"Describí el fallo en3 a400 caracteres.","aprendizaje_local");add(c,"user_report",text,"Pendiente de una reproducción y evaluación comprobada.",0);return MobileCore.say(c,"Guardé el fallo como reporte tuyo. No cambié código ni lo marqué como una mejora verificada.","aprendizaje_local");}return null;}
}
